<script setup>
import FarmExpenseClassification from '../components/FarmExpenseClassification.vue';
import {ref,computed,watch,onBeforeUnmount} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {useContext} from '../composables/context.js';
import {useAccess} from '../composables/access.js';
import {supplierInvoices as api,supplierError} from '../services/supplier-invoices.js';
import {api as accountingApi} from '../services/accounting.js';
import {integrationIssues} from '../services/integrations.js';
import TradeTabs from '../components/TradeTabs.vue';
import FormDialog from '../components/FormDialog.vue';
import InvoicePdfViewer from '../components/InvoicePdfViewer.vue';
import InvoiceForm from '../components/InvoiceForm.vue';
const {company,selectedId,selectExercise}=useContext(),{can}=useAccess(),route=useRoute(),router=useRouter();
const rows=ref([]),kind=ref('invoice'),search=ref(''),page=ref(1),busy=ref(false),loading=ref(false),error=ref(''),notice=ref(''),selected=ref(null),draft=ref(null),pdfUrl=ref(''),remember=ref(false),posting=ref(null),reception=ref(null),mailboxes=ref([]),importErrors=ref([]),mailboxForm=ref({email:'',startDate:''});let generation=0;
const editable=computed(()=>can('accounting_write')&&selected.value&&!selected.value.reception_id&&selected.value.status==='draft');
const newTax=()=>({taxType:'vat',taxRate:'',taxableBase:'',taxAmount:'',exemptionReason:''});
function close(){selected.value=null;draft.value=null;reception.value=null;if(pdfUrl.value)URL.revokeObjectURL(pdfUrl.value);pdfUrl.value='';}
async function load(){const current=++generation;loading.value=true;try{const [records,boxes,errors]=await Promise.all([api.list({kind:kind.value,search:search.value,page:page.value}),api.mailboxes(),api.errors()]);if(current===generation){rows.value=records;mailboxes.value=boxes;importErrors.value=errors;}}catch(cause){if(current===generation)error.value=supplierError(cause);}finally{if(current===generation)loading.value=false;}}
watch(()=>company.value?.id,()=>{close();posting.value=null;rows.value=[];error.value='';notice.value='';page.value=1;void load();},{immediate:true});
watch(kind,()=>{page.value=1;void load();});
watch([()=>route.query.state,()=>company.value?.id],async([state])=>{if(!state)return;const companyId=Number(sessionStorage.getItem('supplier-gmail-company'));if(companyId!==company.value?.id){error.value='Selecciona l’empresa amb què has iniciat la connexió Gmail.';return;}await run(async()=>{if(route.query.error)throw {code:'GMAIL_REAUTHORIZE'};await api.complete({state:String(state),code:String(route.query.code||'')});notice.value='Bústia connectada.';await router.replace({path:route.path,query:{}});await load();});},{immediate:true});
async function run(action){if(busy.value)return;busy.value=true;error.value='';try{await action();}catch(cause){error.value=supplierError(cause);}finally{busy.value=false;}}
async function open(record){await run(async()=>{close();const current=generation;const data=await api.get(record.id),url=await api.pdf(record.id);if(current!==generation){URL.revokeObjectURL(url);return;}selected.value=data;pdfUrl.value=url;const d=structuredClone(data.supplier_draft);draft.value={supplier:{name:'',taxId:'',address:'',email:'',...d.supplier},invoiceNumber:'',invoiceDate:'',dueDate:'',currency:'',description:'',invoiceType:'standard',taxBreakdown:[],withholdings:[],lines:[],total:'',...d};draft.value.supplier={name:'',taxId:'',address:'',email:'',...d.supplier};draft.value.rectification=d.rectification||{reason:'',originalInvoiceNumber:''};remember.value=false;if(data.reception_id)reception.value=await accountingApi('/integration-invoices/'+data.reception_id);});}
async function classify(record,target){await run(async()=>{const result=await api.classify(record.id,target,record.version);if(selected.value?.id===record.id)selected.value={...selected.value,...result};await load();});}
function serialized(){const d=JSON.parse(JSON.stringify(draft.value));if(d.invoiceType==='standard')delete d.rectification;return d;}
async function save(validate=false){const companyId=company.value?.id,documentId=selected.value.id;await run(async()=>{const result=await api.save(documentId,{version:selected.value.version,draft:serialized(),rememberSupplier:remember.value});if(company.value?.id!==companyId)return;selected.value=result;notice.value=result.templateWarning||'Dades guardades.';if(validate){await api.validate(documentId,result.version);if(company.value?.id!==companyId)return;const refreshed=await api.get(documentId);if(company.value?.id!==companyId)return;selected.value=refreshed;const received=await accountingApi('/integration-invoices/'+refreshed.reception_id);if(company.value?.id!==companyId)return;reception.value=received;notice.value='Factura validada i rebuda. Pendent de comptabilitzar.';}await load();});}
async function upload(event){const files=Array.from(event.target.files||[]),companyId=company.value?.id,exerciseId=selectedId.value;await run(async()=>{for(const file of files){if(company.value?.id!==companyId)return;const result=await api.upload(file,exerciseId);if(company.value?.id!==companyId)return;notice.value=result.replayed?'El PDF ja estava arxivat.':'PDF importat. Pendent de revisió.';}await load();});event.target.value='';}
async function configure(){await run(async()=>{mailboxes.value=await api.configure(mailboxForm.value);mailboxForm.value={email:'',startDate:''};});}
async function authorize(box){await run(async()=>{const result=await api.authorize(box.id);sessionStorage.setItem('supplier-gmail-company',String(company.value.id));window.location.assign(result.url);});}
async function sync(box){await run(async()=>{const result=await api.sync(box.id,selectedId.value);notice.value=`${result.imported} importats · ${result.duplicates} duplicats · ${result.errors} errors`;await load();});}
async function disconnect(box){await run(async()=>{await api.disconnect(box.id);await load();});}
function beginPosting(){const r=reception.value;selectExercise(String(r.form.exercise_id));close();posting.value=r;}
async function posted(){posting.value=null;notice.value='Factura comptabilitzada.';await load();}
const status=row=>row.reception_id?({posted:'Comptabilitzada',cancelled:'Recepció anul·lada',issues:'Validada · revisar incidències',rectified:'Rectificada'}[row.reception_status]||'Validada · rebuda'):['posted','linked'].includes(row.status)?'Comptabilitzada':row.review_kind==='not_invoice'?'No factura':'Pendent de revisió';
onBeforeUnmount(()=>{generation++;close();});
</script>
<template>
 <TradeTabs/><div class="page-heading"><h1>Factures de proveïdors</h1><label v-if="can('accounting_write')" class="button primary">Importar PDF<input type="file" accept="application/pdf" multiple :disabled="busy||!selectedId" @change="upload"></label></div>
 <p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><p v-if="notice" class="notice" role="status">{{ notice }}</p>
 <div class="actions"><button class="button" :class="{primary:kind==='invoice'}" @click="kind='invoice'">Factures</button><button class="button" :class="{primary:kind==='not_invoice'}" @click="kind='not_invoice'">No factures</button></div>
 <form class="filters" @submit.prevent="page=1;load()"><label>Cercar<input v-model="search" maxlength="200" type="search"></label><button class="button" :disabled="busy||loading">Actualitzar</button></form>
 <div class="table-wrap panel"><table><thead><tr><th>Document</th><th>Proveïdor</th><th>Estat</th><th>Accions</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{ row.reference||row.source_name }}<small class="trade-cell-note">{{ row.source_name }}</small></td><td>{{ row.party_name }}<small class="trade-cell-note">{{ row.party_tax_id }}</small></td><td>{{ status(row) }}</td><td><div class="actions"><button class="button" :disabled="busy" @click="open(row)">Obrir</button><button v-if="can('accounting_write')&&!row.reception_id&&row.status==='draft'" class="button" :disabled="busy" @click="classify(row,kind==='invoice'?'not_invoice':'invoice')">{{ kind==='invoice'?'No és una factura':'Marcar com a factura' }}</button></div></td></tr><tr v-if="!rows.length"><td colspan="4">{{ loading?'Carregant…':'Sense documents' }}</td></tr></tbody></table></div>
 <div class="actions"><button class="button" :disabled="page===1||loading" @click="page--;load()">Anterior</button><span>Pàgina {{ page }}</span><button class="button" :disabled="rows.length<50||loading" @click="page++;load()">Següent</button></div>
 <details><summary>Bústies Gmail</summary><form v-if="can('accounting_write')" class="filters" @submit.prevent="configure"><label>Correu<input v-model="mailboxForm.email" type="email" required maxlength="254"></label><label>Importar des de<input v-model="mailboxForm.startDate" type="date" required></label><button class="button" :disabled="busy">Guardar bústia</button></form><ul><li v-for="box in mailboxes" :key="box.id"><strong>{{ box.email }}</strong> · {{ box.start_date }} · {{ box.connected?'Connectada':'Desconnectada' }}<span v-if="box.last_sync_at"> · {{ box.last_sync_at }}</span><p v-if="box.last_error" role="alert">{{ box.last_error }}</p><div v-if="can('accounting_write')" class="actions"><button class="button" :disabled="busy" @click="authorize(box)">Connectar Gmail</button><button class="button" :disabled="busy||!box.connected||!selectedId" @click="sync(box)">Importar correus</button><button class="button" :disabled="busy||!box.connected" @click="disconnect(box)">Desconnectar</button></div></li></ul></details>
 <details v-if="importErrors.length"><summary>Errors d’importació ({{ importErrors.length }})</summary><ul><li v-for="item in importErrors" :key="item.id">{{ item.created_at }} · {{ item.source_id }} · {{ item.error_code }}</li></ul></details>
 <FormDialog v-if="selected&&draft" class="supplier-review-dialog" :title="selected.source_name" :busy="busy" @close="close">
  <p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
  <div class="supplier-review"><InvoicePdfViewer v-if="pdfUrl" :src="pdfUrl" :title="selected.source_name"/><section>
   <div class="actions"><span class="badge">{{ status(selected) }}</span><button v-if="editable" class="button" :disabled="busy" @click="classify(selected,selected.review_kind==='invoice'?'not_invoice':'invoice')">{{ selected.review_kind==='invoice'?'No és una factura':'Marcar com a factura' }}</button></div>
   <form v-if="selected.review_kind==='invoice'" novalidate @submit.prevent="save(false)"><fieldset :disabled="busy||!editable">
    <div class="supplier-fields"><label v-for="[key,label] in [['name','Proveïdor'],['taxId','NIF'],['address','Adreça'],['email','Correu']]" :key="key">{{ label }}<input v-model="draft.supplier[key]" :type="key==='email'?'email':'text'"></label></div>
    <div class="supplier-fields"><label>Número de factura<input v-model="draft.invoiceNumber" type="text" maxlength="60"></label><label>Data<input v-model="draft.invoiceDate" type="date"></label><label>Venciment<input v-model="draft.dueDate" type="date"></label><label>Moneda<input v-model="draft.currency" maxlength="3" placeholder="EUR"></label></div>
    <label>Concepte<textarea v-model="draft.description" maxlength="1000"/></label><label>Tipus<select v-model="draft.invoiceType"><option value="standard">Factura ordinària</option><option value="credit_note">Abonament</option><option value="rectifying">Rectificativa</option></select></label>
    <template v-if="draft.invoiceType!=='standard'"><label>Factura original<input v-model="draft.rectification.originalInvoiceNumber" maxlength="60"></label><label>Motiu<input v-model="draft.rectification.reason" maxlength="250"></label></template>
    <h3>Bases i impostos</h3><div v-for="(tax,index) in draft.taxBreakdown" :key="index" class="supplier-tax"><label>Tractament<select v-model="tax.taxType"><option value="vat">IVA</option><option value="exempt">Exempt</option><option value="not_subject">No subjecte</option><option value="reverse_charge">Inversió subjecte passiu</option></select></label><label v-for="[key,label] in [['taxableBase','Base'],['taxRate','Tipus %'],['taxAmount','Quota']]" :key="key">{{ label }}<input v-model="tax[key]" inputmode="decimal"></label><label v-if="tax.taxType==='exempt'">Motiu d’exempció<input v-model="tax.exemptionReason" maxlength="250"></label><button type="button" class="button" @click="draft.taxBreakdown.splice(index,1)">Treure</button></div><button type="button" class="button" :disabled="draft.taxBreakdown.length>=40" @click="draft.taxBreakdown.push(newTax())">Afegir base</button>
    <h3>Retencions</h3><div v-for="(item,index) in draft.withholdings" :key="index" class="supplier-tax"><label v-for="[key,label] in [['base','Base'],['rate','Tipus %'],['amount','Import']]" :key="key">{{ label }}<input v-model="item[key]" inputmode="decimal"></label><button type="button" class="button" @click="draft.withholdings.splice(index,1)">Treure</button></div><button type="button" class="button" :disabled="draft.withholdings.length>=10" @click="draft.withholdings.push({base:'',rate:'',amount:''})">Afegir retenció</button>
    <details><summary>Línies opcionals</summary><div v-for="(line,index) in draft.lines" :key="index" class="supplier-tax"><label>Descripció<input v-model="line.description" maxlength="200"></label><label v-for="[key,label] in [['taxableBase','Base'],['taxRate','IVA %'],['taxAmount','Quota']]" :key="key">{{ label }}<input v-model="line[key]" inputmode="decimal"></label><button type="button" class="button" @click="draft.lines.splice(index,1)">Treure</button></div><button type="button" class="button" :disabled="draft.lines.length>=200" @click="draft.lines.push({...newTax(),description:''})">Afegir línia</button></details>
    <label>Total<input v-model="draft.total" inputmode="decimal"></label><label class="supplier-check"><input v-model="remember" type="checkbox">Recordar aquest format del proveïdor</label>
   </fieldset><div v-if="editable" class="actions"><button type="submit" class="button" :disabled="busy">Guardar dades</button><button type="button" class="button primary" :disabled="busy" @click="save(true)">Validar i rebre</button></div></form>
   <FarmExpenseClassification v-if="selected.review_kind==='invoice'" source-kind="document" :source-id="selected.id"/>
   <template v-if="reception"><p v-if="reception.issues.length" class="notice">{{ reception.issues.map(key=>integrationIssues[key]||key).join(' · ') }}</p><p>Validada per {{ selected.validated_by }} · {{ selected.validated_at }}</p><button v-if="can('accounting_write')&&reception.can_post" class="button primary" :disabled="busy" @click="beginPosting">Preparar comptabilització</button><RouterLink v-if="reception.invoice_id" :to="{path:'/facturas',query:{invoice_id:reception.invoice_id,company_id:company.id,exercise_id:reception.exercise_id}}">Veure factura comptabilitzada</RouterLink></template>
   <details v-if="selected.extraction.warnings?.length"><summary>Lectura del document</summary><ul><li v-for="warning in selected.extraction.warnings" :key="warning">{{ warning }}</li></ul></details><details><summary>Historial</summary><ul><li v-for="(item,index) in selected.history" :key="index">{{ item.created_at }} · {{ item.actor }} · {{ item.action }}</li></ul></details>
  </section></div>
 </FormDialog>
 <InvoiceForm v-if="posting" direction="received" :initial-value="posting.form" :integration-id="posting.id" :integration-version="posting.version" :entry-candidates="posting.entry_candidates" @close="posting=null" @saved="posted"/>
</template>
<style scoped>
.supplier-review{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px}.supplier-review section{min-width:0}.supplier-fields,.supplier-tax{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:12px 0}.supplier-review label{display:flex;flex-direction:column;gap:6px;margin:10px 0}.supplier-review input,.supplier-review select,.supplier-review textarea{width:100%;box-sizing:border-box}.supplier-review fieldset{border:0;padding:0;min-width:0}.supplier-review .supplier-check{flex-direction:row;align-items:center}.supplier-check input{width:auto}.page-heading input[type=file]{display:block;max-width:230px}details{margin:20px 0}li{margin:12px 0}@media(max-width:850px){.supplier-review{grid-template-columns:1fr}}
</style>
<style>.form-dialog.supplier-review-dialog{width:min(1500px,96vw);max-width:96vw}</style>
